    "factor_updates": [
      {
        "factor": "Altman Z-score distress indicator (Z < 1.8)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Frontier's Z-score around 0.38–0.39 places it in the distress zone, historically associated with high bankruptcy probability within 1–2 years."
      },
      {
        "factor": "Near-term liquidity and debt-maturity profile plus merger certainty",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Liquidity ~$2.3B (6/30/2025) and no maturities before 2027, coupled with Verizon merger proximity, materially reduce near-term bankruptcy risk."
      },
      {
        "factor": "Verizon acquisition close timing and certainty",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "All-cash $20B deal with expected close by early 2026 lowers bankruptcy odds if the deal completes."
      },
      {
        "factor": "Industry distress signal from Spirit Airlines' bankruptcy",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spirit’s Chapter 11 and sector strain provide macro risk pressure that can elevate Frontier's risk profile."
      },
      {
        "factor": "Forecast consensus dispersion and lack of explicit near-term forecast",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Divergent forecasts reflect uncertainty rather than a decisive directional signal for Frontier."
      }
    ],
    "synthesis_rationale": "The posterior of 0.79 results from anchoring in the distressed ULCC reference class (0.35) and applying a sequence of updates: a strong upmove from the low Z-score, balanced by strong downmoves from liquidity/merger catalysts, a moderate downmove from the Verizon close, a moderate upmove from industry distress, and a neutral influence from forecast dispersion. Calibration acknowledges model divergence and the potential for near-term resolution via the merger, yielding a relatively tight, high-confidence posterior in the 0.70–0.88 range."
  }
}

